@import "tailwindcss";

/* ------------------------------------------------------------------ *
 * Maester Cloud — design tokens
 * Clean, light, modern-minimal SaaS palette (plane.so-inspired),
 * monochrome neutral zinc base + a near-black primary, with semantic
 * security colors. No brand purple.
 * ------------------------------------------------------------------ */
@theme {
  --font-sans: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "Geist Mono", ui-monospace, "SFMono-Regular", Menlo, monospace;

  /* surfaces */
  --color-paper: #ffffff;
  --color-canvas: #fafafa;
  --color-subtle: #f4f4f5;

  /* ink */
  --color-ink: #18181b;
  --color-ink-2: #3f3f46;
  --color-ink-3: #71717a;
  --color-line: #e4e4e7;
  --color-line-2: #f0f0f1;

  /* brand primary (monochrome near-black) */
  --color-brand: #111113;
  --color-brand-2: #000000;
  --color-brand-soft: #f4f4f5;
  --color-brand-ink: #18181b;

  /* semantic security */
  --color-pass: #16a34a;
  --color-pass-soft: #dcfce7;
  --color-pass-ink: #15803d;
  --color-fail: #dc2626;
  --color-fail-soft: #fee2e2;
  --color-warn: #d97706;
  --color-warn-soft: #fef3c7;
}

html {
