import re
from html.parser import HTMLParser
void={'meta','link','br','img','input','hr','circle','line','path','polyline','rect'}
for f in ['Main.dc.html','Sponsor.dc.html']:
  s=open(f).read()
  markup=s[:s.index('<script type="text/x-dc"')]
  class P(HTMLParser):
    def __init__(s):super().__init__();s.st=[];s.err=[]
    def handle_starttag(s,t,a):
      if t not in void: s.st.append((t,s.getpos()))
    def handle_endtag(s,t):
      if t in void: return
      if s.st and s.st[-1][0]==t: s.st.pop()
      else: s.err.append((t,s.getpos(),s.st[-1] if s.st else None))
  p=P();p.feed(markup)
  print(f,'errors',p.err[:5],'open',[x for x in p.st if x[0] not in('html','body','x-dc')][:5])
  loopvars=set(re.findall(r'as="(\w+)"',markup))
  used=set(v.split('.')[0] for v in re.findall(r'\{\{\s*([\w.]+)\s*\}\}',markup))
  js=s[s.index('<script type="text/x-dc"'):]
  missing=[u for u in used-loopvars if not re.search(r'\b'+u+r'\b\s*[:,]',js) and u not in('true','false')]
  print(' missing data keys:',missing)
