// One-off conversion of the Docusaurus content in website/ to Astro + Starlight syntax.
// Usage: node convert-content.mjs <website dir>
import { execFileSync } from "node:child_process";
import { readdirSync, readFileSync, statSync, writeFileSync, existsSync } from "node:fs";
import { basename, dirname, join, relative } from "node:path";

const site = process.argv[2];
const roots = ["docs", "versioned_docs/version-2.3.0", "blog"].map((r) => join(site, r));
const skipDirs = new Set(["tests"]);
const report = { renamed: [], edited: 0 };

function walk(dir, out = []) {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) {
      if (skipDirs.has(name) && dir.endsWith("docs")) continue;
      walk(p, out);
    } else if (/\.mdx?$/.test(name)) out.push(p);
  }
  return out;
}

// Text outside fenced code blocks, so JSX detection ignores code samples.
function prose(text) {
  return text.replace(/^(```|~~~)[\s\S]*?^\1/gm, "");
}

function needsMdx(text) {
  const p = prose(text.replace(/^---[\s\S]*?^---/m, ""));
  return /^import\s/m.test(p) || /<(IIcon|FAIcon|Tabs|TabItem|TOCInline|DocLinkList|[A-Z][A-Za-z]+)[\s/>]/.test(p);
}

function convertFrontmatter(fm, isBlog) {
  const lines = fm.split("\n");
  const out = [];
  const sidebar = {};
  for (const line of lines) {
    const m = line.match(/^([a-z_]+):\s*(.*)$/);
    if (!m) { out.push(line); continue; }
    const [, key, value] = m;
    switch (key) {
      case "sidebar_class_name":
      case "hide_title":
      case "id":
        break;
      case "custom_edit_url":
        out.push(`editUrl: ${value}`);
        break;
      case "hide_table_of_contents":
        if (value.trim() === "true") out.push("tableOfContents: false");
        break;
      case "sidebar_position":
        sidebar.order = value.trim();
        break;
      case "sidebar_label":
        sidebar.label = value.trim();
        break;
      default:
        out.push(line);
    }
  }
  if (Object.keys(sidebar).length) {
    out.push("sidebar:");
    if (sidebar.label) out.push(`  label: ${sidebar.label}`);
    if (sidebar.order) out.push(`  order: ${sidebar.order}`);
  }
  return out.join("\n");
}

const admonitionMap = { info: "note", warning: "caution", note: "note", tip: "tip", caution: "caution", danger: "danger", important: "note" };

function convertBody(body, file) {
  let b = body;
  // Tabs
  b = b.replace(/^import\s+Tabs\s+from\s+['"]@theme\/Tabs['"];?\s*\n/m, "");
  b = b.replace(/^import\s+TabItem\s+from\s+['"]@theme\/TabItem['"];?\s*\n/m, "");
  if (/<Tabs[\s>]/.test(b)) b = `import { Tabs, TabItem } from '@astrojs/starlight/components';\n` + b;
  b = b.replace(/<Tabs([^>]*)>/g, (_, attrs) => {
    const g = attrs.match(/groupId=["']([^"']+)["']/);
    return g ? `<Tabs syncKey="${g[1]}">` : "<Tabs>";
  });
  b = b.replace(/<TabItem([^>]*)>/g, (_, attrs) => {
    const label = attrs.match(/label=["']([^"']+)["']/) ?? attrs.match(/value=["']([^"']+)["']/);
    return `<TabItem label="${label ? label[1] : "Tab"}">`;
  });
  // TOCInline: Starlight shows the page table of contents already.
  b = b.replace(/^import\s+TOCInline\s+from\s+['"]@theme\/TOCInline['"];?\s*\n/m, "");
  b = b.replace(/^<TOCInline[^>]*\/>\s*\n/m, "");
  // DocLinkList (command reference index) becomes a generated list.
  b = b.replace(/^import\s+DocLinkList\s+from\s+['"][^'"]+['"];?\s*\n/m, "import CommandList from '@components/CommandList.astro';\n");
  b = b.replace(/<DocLinkList\s*\/>/g, "<CommandList />");
  // Icons
  if (/<IIcon[\s/>]/.test(prose(b)) && !/import IIcon/.test(b)) b = `import IIcon from '@components/IIcon.astro';\n` + b;
  // Imported Markdown partials: use their Content export, and follow renames to .mdx.
  b = b.replace(/^import\s+(\w+)\s+from\s+['"](\.{1,2}\/[^'"]+\.mdx?)['"];?/gm, (_, name, path) => {
    const resolved = join(dirname(file), path);
    let p = path;
    if (!existsSync(resolved) && existsSync(resolved.replace(/\.md$/, ".mdx"))) p = path.replace(/\.md$/, ".mdx");
    if (/\.mdx?$/.test(p) && !/\.(mp4|jpg|png)$/.test(p)) return `import { Content as ${name} } from '${p}';`;
    return `import ${name} from '${p}';`;
  });
  // Admonitions
  b = b.replace(/^(\s*):::(info|warning|note|tip|caution|danger|important)(?:[ \t]+(.+))?$/gm, (_, indent, type, title) => {
    const t = admonitionMap[type];
    return title ? `${indent}:::${t}[${title.trim()}]` : `${indent}:::${t}`;
  });
  // Blog excerpt marker
  b = b.replace(/<!--\s*truncate\s*-->/g, "<!-- excerpt -->");
  b = b.replace(/\{\/\*\s*truncate\s*\*\/\}/g, "<!-- excerpt -->");
  // Preview docs now live at /docs
  b = b.replace(/\]\(\/docs\/next\//g, "](/docs/");
  b = b.replace(/(["'(])https:\/\/maester\.dev\/docs\/next\//g, "$1https://maester.dev/docs/");
  b = b.replace(/@site\/static\//g, "/");
  return b;
}

const files = roots.flatMap((r) => (existsSync(r) ? walk(r) : []));
for (let file of files) {
  const isBlog = file.includes("/blog/");
  let text = readFileSync(file, "utf8").replace(/\r\n/g, "\n");
  const fmMatch = text.match(/^---\n([\s\S]*?)\n---\n?/);
  let fm = fmMatch ? fmMatch[1] : null;
  let body = fmMatch ? text.slice(fmMatch[0].length) : text;
  if (fm !== null) fm = convertFrontmatter(fm, isBlog);
  body = convertBody(body, file);
  const out = (fm !== null ? `---\n${fm}\n---\n` : "") + body;
  if (file.endsWith(".md") && needsMdx(out)) {
    const target = file.replace(/\.md$/, ".mdx");
    execFileSync("git", ["mv", file, target], { cwd: site });
    report.renamed.push(relative(site, target));
    file = target;
  }
  writeFileSync(file, out);
  report.edited++;
}
console.log(JSON.stringify(report, null, 1));

