// The site's one content collection: the guides and command reference in website/docs, the generated test
// pages, the frozen 2.x docs and the blog. Each source keeps its own folder; this loader gives every page the
// URL it had on the Docusaurus site.
import { execFileSync } from 'node:child_process';
import { glob, type Loader, type LoaderContext } from 'astro/loaders';

// A glob loader removes the entries it did not see on its last pass. Each source sees only its own entries,
// so the sources don't remove each other's pages.
function scoped(context: LoaderContext, prefix: string): LoaderContext {
	const own = (id: string) => id.startsWith(prefix);
	const store = new Proxy(context.store, {
		get(target, property, receiver) {
			if (property === 'keys') return () => target.keys().filter(own);
			if (property === 'values') return () => target.values().filter((entry) => own(entry.id));
			if (property === 'entries') return () => target.entries().filter(([id]) => own(id));
			if (property === 'clear') return () => target.keys().filter(own).forEach((id) => target.delete(id));
			const value = Reflect.get(target, property, receiver);
			return typeof value === 'function' ? value.bind(target) : value;
		},
	});
	return { ...context, store };
}

// docs/connect-maester/readme.md -> connect-maester, like Docusaurus: a readme or index is its folder's page.
function pathId(entry: string): string {
	const parts = entry.replace(/\.mdx?$/, '').split('/');
	if (parts.length > 0 && /^(readme|index)$/i.test(parts.at(-1)!)) parts.pop();
	return parts.join('/');
}

const join = (...parts: string[]) => parts.filter(Boolean).join('/');

const sources = [
	glob({
		pattern: ['**/*.{md,mdx}'],
		base: './docs',
		generateId: ({ entry }) => join('docs', pathId(entry)),
	}),
	glob({
		pattern: ['**/*.{md,mdx}'],
		base: './.generated/tests',
		generateId: ({ entry, data }) => (typeof data.slug === 'string' ? data.slug : join('docs/tests', pathId(entry))),
	}),
	glob({
		pattern: ['**/*.{md,mdx}'],
		base: './versioned_docs/version-2.3.0',
		generateId: ({ entry }) => join('docs/2.x', pathId(entry)),
	}),
	glob({
		pattern: ['*/index.{md,mdx}'],
		base: './blog',
		generateId: ({ entry, data }) => join('blog', typeof data.slug === 'string' ? data.slug : entry.split('/')[0]),
	}),
];
const prefixes = ['docs/', 'docs/tests', 'docs/2.x', 'blog/'];

export function maesterLoader(): Loader {
	return {
		name: 'maester-content',
		async load(context) {
			// The test pages are written from src/data/test-catalog.json before they are loaded.
			execFileSync(process.execPath, ['scripts/generate-test-docs.mjs'], { stdio: 'inherit' });
			for (const [index, source] of sources.entries()) {
				const prefix = prefixes[index];
				// docs/ also matches the tests and the 2.x archive: keep those out of the guides' scope.
				const context_ = scoped(context, prefix);
				if (prefix === 'docs/') {
					const exclude = (id: string) => id.startsWith('docs/tests') || id.startsWith('docs/2.x');
					const store = context_.store;
					context_.store = new Proxy(store, {
						get(target, property, receiver) {
							if (property === 'keys') return () => target.keys().filter((id: string) => !exclude(id));
							if (property === 'values') return () => target.values().filter((entry: { id: string }) => !exclude(entry.id));
							if (property === 'entries') return () => target.entries().filter(([id]: [string]) => !exclude(id));
							const value = Reflect.get(target, property, receiver);
							return typeof value === 'function' ? value.bind(target) : value;
						},
					});
				}
				await source.load(context_);
			}
		},
	};
}

// The site's one content collection: the guides and command reference in website/docs, the generated test
// pages, the frozen 2.x docs and the blog. Each source keeps its own folder; this loader gives every page the
// URL it had on the Docusaurus site.
import { execFileSync } from 'node:child_process';
import { glob, type Loader, type LoaderContext } from 'astro/loaders';

type Owns = (id: string) => boolean;

// A glob loader removes the entries it did not see on its last pass. Each source sees only its own entries,
// so the sources don't remove each other's pages.
function scoped(context: LoaderContext, owns: Owns): LoaderContext {
	const store = new Proxy(context.store, {
		get(target, property, receiver) {
			if (property === 'keys') return () => target.keys().filter(owns);
			if (property === 'values') return () => target.values().filter((entry) => owns(entry.id));
			if (property === 'entries') return () => target.entries().filter(([id]) => owns(id));
			if (property === 'clear') return () => target.keys().filter(owns).forEach((id) => target.delete(id));
			const value = Reflect.get(target, property, receiver);
			return typeof value === 'function' ? value.bind(target) : value;
		},
	});
	return { ...context, store };
}

// docs/connect-maester/readme.md -> connect-maester, like Docusaurus: a readme or index is its folder's page.
function pathId(entry: string): string {
	const parts = entry.replace(/\.mdx?$/, '').split('/');
	if (parts.length > 0 && /^(readme|index)$/i.test(parts.at(-1)!)) parts.pop();
	return parts.join('/');
}

const join = (...parts: string[]) => parts.filter(Boolean).join('/');
const isTest = (id: string) => id === 'docs/tests' || id.startsWith('docs/tests/');
const isArchive = (id: string) => id === 'docs/2.x' || id.startsWith('docs/2.x/');

const sources: { owns: Owns; loader: Loader }[] = [
	{
		owns: (id) => id.startsWith('docs/') && !isTest(id) && !isArchive(id),
		loader: glob({
			pattern: ['**/*.{md,mdx}'],
			base: './docs',
			generateId: ({ entry }) => join('docs', pathId(entry)),
		}),
	},
	{
		owns: isTest,
		loader: glob({
			pattern: ['**/*.{md,mdx}'],
			base: './.generated/tests',
			generateId: ({ entry, data }) => (typeof data.slug === 'string' ? data.slug : join('docs/tests', pathId(entry))),
		}),
	},
	{
		owns: isArchive,
		loader: glob({
			pattern: ['**/*.{md,mdx}'],
			base: './versioned_docs/version-2.3.0',
			generateId: ({ entry }) => join('docs/2.x', pathId(entry)),
		}),
	},
	{
		owns: (id) => id.startsWith('blog/'),
		loader: glob({
			pattern: ['*/index.{md,mdx}'],
			base: './blog',
			generateId: ({ entry, data }) => join('blog', typeof data.slug === 'string' ? data.slug : entry.split('/')[0]),
		}),
	},
];

export function maesterLoader(): Loader {
	return {
		name: 'maester-content',
		async load(context) {
			// The test pages are written from src/data/test-catalog.json before they are loaded.
			execFileSync(process.execPath, ['scripts/generate-test-docs.mjs'], { stdio: 'inherit' });
			for (const { owns, loader } of sources) await loader.load(scoped(context, owns));
		},
	};
}

import { defineCollection } from 'astro:content';
import { z } from 'astro/zod';
import { docsSchema } from '@astrojs/starlight/schema';
import { blogSchema } from 'starlight-blog/schema';
import { topicSchema } from 'starlight-sidebar-topics/schema';
import { maesterLoader } from './lib/content-loader';

export const collections = {
	docs: defineCollection({
		loader: maesterLoader(),
		schema: docsSchema({
			extend: (context) =>
				blogSchema(context)
					.extend(topicSchema.shape)
					.extend({
						// Facts about a generated test or command page, for its version notes.
						maester: z
							.object({
								kind: z.enum(['test', 'command']),
								id: z.string(),
								suite: z.string().optional(),
								severity: z.string().optional(),
								product: z.string().optional(),
								feature: z.string().optional(),
								previewOnly: z.boolean().default(false),
								previewCheck: z.boolean().default(false),
							})
							.optional(),
						// A guide section or page that only applies from this release: see the versions guide.
						since: z.string().optional(),
						// Blog posts from the Docusaurus site: the social card and its text.
						image: z.string().optional(),
						card_headline: z.string().optional(),
						card_label: z.string().optional(),
						note: z.string().optional(),
					}),
		}),
	}),
};

