// @ts-check
import { readFileSync } from 'node:fs';
import react from '@astrojs/react';
import sitemap from '@astrojs/sitemap';
import starlight from '@astrojs/starlight';
import { defineConfig } from 'astro/config';
import { load as loadYaml } from 'js-yaml';
import starlightBlog from 'starlight-blog';
import starlightLlmsTxt from 'starlight-llms-txt';
import starlightSidebarTopics from 'starlight-sidebar-topics';
import { rehypeCommandParameters } from './src/lib/rehype-command-parameters.mjs';
import { remarkDocLinks } from './src/lib/remark-doc-links.mjs';

const site = 'https://maester.dev';

// Blog authors, from the Docusaurus authors file.
const authorsFile = /** @type {Record<string, {name: string, title?: string, image_url?: string, url?: string, socials?: Record<string, string>}>} */ (
	loadYaml(readFileSync(new URL('./blog/authors.yml', import.meta.url), 'utf8'))
);
const authors = Object.fromEntries(
	Object.entries(authorsFile).map(([id, a]) => [
		id,
		{ name: a.name, title: a.title, picture: a.image_url, url: a.url ?? (a.socials?.github ? `https://github.com/${a.socials.github}` : undefined) },
	]),
);

const posthogKey = 'REDACTED';

export default defineConfig({
	site,
	trailingSlash: 'never',
	// docs/intro.html is served at /docs/intro: the URL every page and the sitemap use, with no redirect.
	build: { format: 'file' },
	vite: {
		resolve: {
			alias: { '@components': new URL('./src/components', import.meta.url).pathname },
		},
	},
	markdown: {
		remarkPlugins: [remarkDocLinks],
		rehypePlugins: [rehypeCommandParameters],
	},
	integrations: [
		sitemap({
			// The 2.x archive and the Markdown partials are not for search engines.
			filter: (page) => !/\/docs\/2\.x(\/|$)|\/docs\/sections\//.test(page),
		}),
		starlight({
			title: 'Maester',
			description: 'Open-source security testing for Microsoft 365, Entra, Azure and Active Directory.',
			logo: { src: './src/assets/maester-mark.svg', alt: 'Maester' },
			favicon: '/favicon.ico',
			customCss: ['./src/styles/theme.css'],
			lastUpdated: false,
			editLink: { baseUrl: 'https://github.com/maester365/maester/edit/main/website/' },
			social: [
				{ icon: 'github', label: 'GitHub', href: 'https://github.com/maester365/maester' },
				{ icon: 'discord', label: 'Discord', href: 'https://discord.maester.dev' },
			],
			components: {
				Head: './src/components/overrides/Head.astro',
				Header: './src/components/overrides/Header.astro',
				PageTitle: './src/components/overrides/PageTitle.astro',
				Sidebar: './src/components/overrides/Sidebar.astro',
				Footer: './src/components/overrides/Footer.astro',
			},
			expressiveCode: {
				themes: ['github-dark-default', 'github-light-default'],
				styleOverrides: { borderRadius: '0.75rem' },
			},
			head: [
				{ tag: 'meta', attrs: { property: 'og:image', content: `${site}/img/maester-social-card.jpg` } },
				{ tag: 'meta', attrs: { name: 'twitter:card', content: 'summary_large_image' } },
			],
			plugins: [
				starlightSidebarTopics(
					[
						{
							id: 'guides',
							label: 'Guides',
							link: '/docs/intro',
							icon: 'open-book',
							items: [
								{ label: 'Get started', items: ['docs/intro', 'docs/installation', 'docs/preview', 'docs/upgrading-from-2x', 'docs/updating-tests'] },
								{ label: 'Connect', autogenerate: { directory: 'docs/connect-maester' } },
								{ label: 'Choose what to run', autogenerate: { directory: 'docs/configuration' } },
								{ label: 'Results', items: ['docs/export-results', 'docs/result-schema', 'docs/ca-what-if'] },
								{ label: 'Automate', autogenerate: { directory: 'docs/monitoring' } },
								{ label: 'Alerts', autogenerate: { directory: 'docs/alerts' } },
								{ label: 'Many tenants', autogenerate: { directory: 'docs/multi-tenant' } },
								{ label: 'Active Directory', items: ['docs/advanced/active-directory'] },
								{ label: 'Write your own tests', items: [{ autogenerate: { directory: 'docs/writing-tests' } }, { label: 'Test builder', link: '/test-builder' }] },
								{ label: 'Community', items: ['docs/watch', 'docs/contributing', 'docs/agents-and-skills', 'docs/faq'] },
							],
						},
						{
							id: 'tests',
							label: 'Test catalog',
							link: '/docs/tests',
							icon: 'list-format',
							items: [
								{ label: 'All checks', link: '/docs/tests' },
								{
									label: 'Suites',
									items: [
										{ label: 'Maester', link: '/docs/tests/maester' },
										{ label: 'CIS', link: '/docs/tests/cis' },
										{ label: 'CISA SCuBA', link: '/docs/tests/cisa' },
										{ label: 'ASD Essential Eight', link: '/docs/tests/asd' },
										{ label: 'Entra ID SCA (EIDSCA)', link: '/docs/tests/eidsca' },
										{ label: 'ORCA', link: '/docs/tests/orca' },
										{ label: 'Active Directory', link: '/docs/tests/ad' },
									],
								},
								{ label: 'Tags from 2.x', link: '/docs/tests/tags' },
							],
						},
						{
							id: 'commands',
							label: 'Commands',
							link: '/docs/commands',
							icon: 'seti:powershell',
							items: [{ label: 'Overview', link: '/docs/commands' }, { label: 'Commands', autogenerate: { directory: 'docs/commands' } }],
						},
						{
							id: 'packs',
							label: 'Packs',
							link: '/docs/packs',
							icon: 'puzzle',
							items: [
								{ label: 'Maester Packs', autogenerate: { directory: 'docs/packs' } },
								{ label: 'Browse packs', link: 'https://packs.maester.cloud', attrs: { target: '_blank' } },
							],
						},
						{
							id: 'blog',
							label: 'Blog',
							link: '/blog',
							icon: 'document',
							items: [{ label: 'All posts', link: '/blog' }],
						},
					],
					{
						topics: {
							tests: ['/docs/tests/**/*'],
							commands: ['/docs/commands/**/*'],
							blog: ['/blog', '/blog/**/*'],
						},
						exclude: ['/docs/2.x', '/docs/2.x/**/*', '/docs/sections/**/*'],
					},
				),
				starlightBlog({
					title: 'Blog',
					authors,
					postCount: 12,
					recentPostCount: 8,
					navigation: 'none',
					metrics: { readingTime: true },
				}),
				starlightLlmsTxt({
					projectName: 'Maester',
					description:
						'Maester is an open-source PowerShell framework that tests the security configuration of Microsoft 365, Entra ID, Azure and Active Directory against CIS, CISA SCuBA, Microsoft guidance and the Zero Trust Assessment.',
					exclude: ['docs/2.x/**', 'docs/sections/**', 'blog/**'],
				}),
			],
		}),
		react(),
	],
});

export { posthogKey };

// The two release channels the site documents, and what each one contains.
//
// website/version-config.js holds the current stable and preview versions; the publish-module workflows update
// it. website/src/data/versions.json holds the release each test, command and parameter first shipped in
// (scripts/update-versions.mjs). Anything not in versions.json is only in the preview.
import { readFileSync } from 'node:fs';

const websiteRoot = new URL('../../', import.meta.url);
const config = readFileSync(new URL('version-config.js', websiteRoot), 'utf8');
const read = (key) => config.match(new RegExp(`${key}:\\s*["']([^"']+)["']`))?.[1] ?? '';

export const stableVersion = read('currentVersion');
// 3.1.0-preview: the release the preview leads to.
export const previewVersion = read('previewVersion');
// 3.1: how the site names the preview in marks such as "New in 3.1".
export const previewLabel = previewVersion.replace(/^(\d+\.\d+)\..*$/, '$1');

const history = JSON.parse(readFileSync(new URL('src/data/versions.json', websiteRoot), 'utf8'));

export const releasedTests = new Set(Object.keys(history.tests));

/** @param {string} name */
export function commandHistory(name) {
	const entry = history.commands[name];
	return entry ? { since: entry.since, parameters: new Set(Object.keys(entry.parameters ?? {})) } : null;
}

// Marks the parameters of a command reference page that are only in the preview: each "-Name" heading whose
// parameter the stable release does not have gets a version mark.
import { commandHistory, previewLabel, stableVersion } from './versions.mjs';

const commandFile = /[\\/]website[\\/]docs[\\/]commands[\\/]([^\\/]+)\.mdx$/;

function text(node) {
	if (node.type === 'text') return node.value;
	return (node.children ?? []).map(text).join('');
}

export function rehypeCommandParameters() {
	return (tree, file) => {
		const name = file.path?.match(commandFile)?.[1];
		if (!name) return;
		const history = commandHistory(name);
		// A command the stable release doesn't have: the page says so once, at the top.
		if (!history) return;
		const visit = (node) => {
			if (node.type === 'element' && node.tagName === 'h3') {
				const parameter = text(node).trim().match(/^-([A-Za-z][A-Za-z0-9]*)$/)?.[1];
				if (parameter && parameter !== 'ProgressAction' && !history.parameters.has(parameter)) {
					node.children.push({
						type: 'element',
						tagName: 'span',
						properties: { className: ['mt-mark'], title: `Not in Maester ${stableVersion}` },
						children: [
							{ type: 'element', tagName: 'span', properties: { className: ['mt-mark__preview'] }, children: [{ type: 'text', value: `New in ${previewLabel}` }] },
							{ type: 'element', tagName: 'span', properties: { className: ['mt-mark__stable'] }, children: [{ type: 'text', value: `Preview ${previewLabel}` }] },
						],
					});
				}
			}
			for (const child of node.children ?? []) visit(child);
		};
		visit(tree);
	};
}

// Turns links to other Markdown files ("./configuration/overview.md#selection") into the URL of that page,
// so the docs read the same on GitHub and on the site.
import { existsSync } from 'node:fs';
import { dirname, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const websiteRoot = fileURLToPath(new URL('../../', import.meta.url));
const roots = [
	{ dir: resolve(websiteRoot, 'docs'), url: '/docs' },
	{ dir: resolve(websiteRoot, 'versioned_docs', 'version-2.3.0'), url: '/docs/2.x' },
];

function urlFor(target) {
	for (const root of roots) {
		const rel = relative(root.dir, target);
		if (rel.startsWith('..')) continue;
		const parts = rel.replace(/\.mdx?$/, '').split(sep);
		if (/^(readme|index)$/i.test(parts.at(-1))) parts.pop();
		// A 2.x command page that is now a test redirects from its current URL.
		if (root.url === '/docs/2.x' && parts[0] === 'commands' && !existsSync(target)) return `/docs/commands/${parts.slice(1).join('/')}`;
		return [root.url, ...parts].join('/');
	}
	return null;
}

export function remarkDocLinks() {
	return (tree, file) => {
		if (!file.path) return;
		const from = dirname(file.path);
		const visit = (node) => {
			if ((node.type === 'link' || node.type === 'definition') && typeof node.url === 'string') {
				const match = node.url.match(/^(?!\w+:|\/|#)([^#?]+\.mdx?)(#.*)?$/);
				if (match) {
					let target = resolve(from, decodeURI(match[1]));
					if (!existsSync(target)) {
						const other = target.endsWith('.md') ? `${target}x` : target.replace(/\.mdx$/, '.md');
						if (existsSync(other)) target = other;
					}
					const url = urlFor(target);
					if (url) node.url = url + (match[2] ?? '');
				}
			}
			for (const child of node.children ?? []) visit(child);
		};
		visit(tree);
	};
}

