const { entry, id } = Astro.locals.starlightRoute;
const isArchive = id === 'docs/2.x' || id.startsWith('docs/2.x/') || id.startsWith('docs/sections/');
const url = new URL(Astro.url.pathname, Astro.site);
const data = entry.data as Record<string, any>;
const image = typeof data.image === 'string' && data.image.startsWith('/') ? new URL(data.image, Astro.site).href : undefined;
const isBlogPost = id.startsWith('blog/') && data.date instanceof Date;
const jsonLd = isBlogPost
	? {
			'@context': 'https://schema.org',
			'@type': 'BlogPosting',
			headline: data.title,
			description: data.description,
			datePublished: data.date.toISOString(),
			url: url.href,
			...(image ? { image } : {}),
		}
	: {
			'@context': 'https://schema.org',
			'@type': 'TechArticle',
			headline: data.title,
			description: data.description,
			url: url.href,
			isPartOf: { '@type': 'WebSite', name: 'Maester', url: 'https://maester.dev' },
		};
