---
// The test catalog: every check, filtered in the browser by text, suite, product and severity, with the
// Invoke-Maester command that runs the same selection. The full table is in the HTML, so it works without
// JavaScript and search engines see every check.
import catalog from '../data/test-catalog.json';
import { previewLabel, releasedTests } from '../lib/versions.mjs';

const productNames = new Map(catalog.Taxonomy.Products.map((p: { Key: string; Name: string }) => [p.Key, p.Name]));
const featureNames = new Map(catalog.Taxonomy.Features.map((f: { Key: string; Name: string }) => [f.Key, f.Name]));
const severityOrder = ['Critical', 'High', 'Medium', 'Low', 'Info'];
const tests = (catalog.Tests as any[])
	.filter((t) => t.Lifecycle !== 'Deprecated')
	.map((t) => ({
		id: t.Id as string,
		title: t.Title as string,
		suite: t.Suite as string,
		product: t.Product as string,
		productName: (productNames.get(t.Product) as string) ?? t.Product,
		feature: (featureNames.get(t.Feature) as string) ?? t.Feature ?? '',
		severity: (t.Severity as string) || 'Info',
		previewOnly: !releasedTests.has(t.Id),
		previewCheck: t.Lifecycle === 'Preview',
	}))
	.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));

const count = <T extends string>(key: (t: (typeof tests)[number]) => T) => {
	const map = new Map<T, number>();
	for (const t of tests) map.set(key(t), (map.get(key(t)) ?? 0) + 1);
	return [...map.entries()].sort((a, b) => b[1] - a[1]);
};
const suites = count((t) => t.suite);
const products = count((t) => t.product);
const severities = severityOrder.map((s) => [s, tests.filter((t) => t.severity === s).length] as const).filter(([, n]) => n > 0);
const previewOnlyCount = tests.filter((t) => t.previewOnly).length;
---

<mt-test-catalog class="mt-cat not-content">
	<div class="mt-cat__bar">
		<input type="search" placeholder={`Search ${tests.length} checks by ID, title or feature`} aria-label="Search checks" data-filter="q" />
		<select aria-label="Suite" data-filter="suite">
			<option value="">All suites</option>
			{suites.map(([s, n]) => <option value={s}>{s} ({n})</option>)}
		</select>
		<select aria-label="Product" data-filter="product">
			<option value="">All products</option>
			{products.map(([p, n]) => <option value={p}>{productNames.get(p) ?? p} ({n})</option>)}
		</select>
		<select aria-label="Severity" data-filter="severity">
			<option value="">All severities</option>
			{severities.map(([s, n]) => <option value={s}>{s} ({n})</option>)}
		</select>
		<label class="mt-cat__toggle"><input type="checkbox" data-filter="preview" /> Only new in {previewLabel} ({previewOnlyCount})</label>
	</div>
	<div class="mt-cat__cmd">
		<code data-cmd>Invoke-Maester</code>
		<button type="button" data-copy>Copy</button>
		<span class="mt-cat__count" data-count>{tests.length} checks</span>
	</div>
	<table>
		<thead>
			<tr><th>ID</th><th>Check</th><th>Product</th><th>Severity</th></tr>
		</thead>
		<tbody>
			{
				tests.map((t) => (
					<tr
						data-q={`${t.id} ${t.title} ${t.feature} ${t.productName}`.toLowerCase()}
						data-suite={t.suite}
						data-product={t.product}
						data-severity={t.severity}
						data-preview={t.previewOnly ? '1' : ''}
					>
						<td class="mt-cat__id">
							<a href={`/docs/tests/${t.id}`}>{t.id}</a>
						</td>
						<td>
							{t.title}
							{t.previewOnly && (
								<span class="mt-mark">
									<span class="mt-mark__preview">New in {previewLabel}</span>
									<span class="mt-mark__stable">Preview {previewLabel}</span>
								</span>
							)}
							{t.previewCheck && <span class="mt-cat__check">-IncludePreview</span>}
						</td>
						<td>{t.productName}</td>
						<td>
							<span class={`mt-cat__sev mt-cat__sev--${t.severity.toLowerCase()}`}>{t.severity}</span>
						</td>
					</tr>
				))
			}
		</tbody>
	</table>
</mt-test-catalog>

<script>
	class TestCatalog extends HTMLElement {
		connectedCallback() {
			const controls = [...this.querySelectorAll<HTMLInputElement | HTMLSelectElement>('[data-filter]')];
			const rows = [...this.querySelectorAll<HTMLTableRowElement>('tbody tr')];
			const cmd = this.querySelector('[data-cmd]')!;
			const countEl = this.querySelector('[data-count]')!;
			const value = (name: string) => {
				const el = controls.find((c) => c.dataset.filter === name)!;
				return el instanceof HTMLInputElement && el.type === 'checkbox' ? (el.checked ? '1' : '') : el.value;
			};
			const apply = () => {
				const q = value('q').trim().toLowerCase();
				const suite = value('suite');
				const product = value('product');
				const severity = value('severity');
				const preview = value('preview');
				let shown = 0;
				for (const row of rows) {
					const d = row.dataset;
					const match =
						(!q || d.q!.includes(q)) &&
						(!suite || d.suite === suite) &&
						(!product || d.product === product) &&
						(!severity || d.severity === severity) &&
						(!preview || d.preview === '1');
					row.hidden = !match;
					if (match) shown++;
				}
				countEl.textContent = `${shown} check${shown === 1 ? '' : 's'}`;
				const parts = ['Invoke-Maester'];
				if (suite) parts.push(`-Suite ${suite}`);
				if (product) parts.push(`-Product ${product}`);
				if (severity) parts.push(`-Severity ${severity}`);
				if (q && shown > 0 && shown <= 5) parts.push(`-TestId ${rows.filter((r) => !r.hidden).map((r) => r.querySelector('a')!.textContent).join(',')}`);
				cmd.textContent = parts.join(' ');
				const params = new URLSearchParams();
				for (const name of ['q', 'suite', 'product', 'severity', 'preview']) if (value(name)) params.set(name, value(name));
				history.replaceState(null, '', params.size ? `?${params}` : location.pathname);
			};
			const initial = new URLSearchParams(location.search);
			for (const c of controls) {
				const v = initial.get(c.dataset.filter!);
				if (v) {
					if (c instanceof HTMLInputElement && c.type === 'checkbox') c.checked = v === '1';
					else c.value = v;
				}
				c.addEventListener('input', apply);
			}
			this.querySelector('[data-copy]')?.addEventListener('click', (e) => {
				navigator.clipboard.writeText(cmd.textContent ?? '');
				(e.target as HTMLButtonElement).textContent = 'Copied';
				setTimeout(() => ((e.target as HTMLButtonElement).textContent = 'Copy'), 1500);
			});
			apply();
		}
	}
	customElements.define('mt-test-catalog', TestCatalog);
</script>

<style>
	.mt-cat {
		display: flex;
		flex-direction: column;
		gap: 0.75rem;
		margin-top: 1rem;
	}
	.mt-cat__bar {
		display: flex;
		flex-wrap: wrap;
		gap: 0.5rem;
		align-items: center;
	}
	.mt-cat__bar input[type='search'] {
		flex: 1 1 18rem;
	}
	.mt-cat__bar :is(input[type='search'], select) {
		font: inherit;
		font-size: 0.875rem;
		background: var(--sl-color-black);
		color: var(--sl-color-white);
		border: 1px solid var(--sl-color-gray-5);
		border-radius: 9px;
		padding: 0.45rem 0.7rem;
	}
	.mt-cat__toggle {
		font-size: 0.85rem;
		display: inline-flex;
		gap: 0.4rem;
		align-items: center;
		color: var(--sl-color-gray-2);
	}
	.mt-cat__cmd {
		display: flex;
		align-items: center;
		gap: 0.6rem;
		flex-wrap: wrap;
		background: #18181b;
		border-radius: 10px;
		padding: 0.55rem 0.8rem;
	}
	.mt-cat__cmd code {
		color: #e4e4e7;
		background: none;
		font-size: 0.85rem;
		flex: 1 1 auto;
		overflow-wrap: anywhere;
	}
	.mt-cat__cmd button {
		font: inherit;
		font-size: 0.78rem;
		font-weight: 600;
		border: 0;
		border-radius: 6px;
		background: #3f3f46;
		color: #fff;
		padding: 0.25rem 0.6rem;
		cursor: pointer;
	}
	.mt-cat__count {
		font-size: 0.78rem;
		color: #a1a1aa;
