<script>
	const diagrams = document.querySelectorAll<HTMLElement>('pre.mermaid');
	if (diagrams.length > 0) {
		const sources = [...diagrams].map((d) => d.textContent ?? '');
		const render = async () => {
			const { default: mermaid } = await import('mermaid');
			const dark = document.documentElement.dataset.theme !== 'light';
			mermaid.initialize({ startOnLoad: false, theme: dark ? 'dark' : 'neutral', fontFamily: 'Inter Variable, Inter, sans-serif' });
