	wide?: boolean;
	jsonLd?: Record<string, unknown>;
}
const { title, description, image = '/img/maester-social-card.jpg', wide = false, jsonLd } = Astro.props;
const canonical = new URL(Astro.url.pathname.replace(/\/$/, '') || '/', Astro.site).href;
