import type { StarlightBlogUserMetrics } from '../schema'

import { transformHTMLForMetrics } from './html'
import { getLangFromLocale, type Locale } from './i18n'

// https://iovs.arvojournals.org/article.aspx?articleid=2166061
// 184 ± 29 words/min → 213 words/min
const wordsPerMinute = 213

export function getMetrics(html: string, locale: Locale, userMetrics: StarlightBlogUserMetrics): Metrics {
  const { content, images } = transformHTMLForMetrics(html)

  const words = userMetrics?.words ?? getWordCount(content, getLangFromLocale(locale))

  let seconds = userMetrics?.readingTime ?? (words / wordsPerMinute) * 60
  if (!userMetrics?.readingTime) seconds = addImagesTime(seconds, images)

  return {
    readingTime: {
      minutes: Math.ceil(seconds / 60),
      seconds: Math.ceil(seconds),
    },
    words: {
      rounded: Math.ceil(words / 100) * 100,
      total: words,
    },
  }
}

function getWordCount(markdown: string, lang: string) {
  const segmenter = new Intl.Segmenter(lang, { granularity: 'word' })
  let wordCount = 0

  for (const segment of segmenter.segment(markdown)) {
    if (segment.isWordLike) wordCount++
  }

  return wordCount
}

