// One button that switches between light and dark. Until someone clicks it the site follows the system
// setting; the choice is kept in localStorage under Starlight's key, so the docs and the other pages agree.
---

<mt-theme-toggle>
	<button type="button" class="mt-theme" aria-label="Switch to dark theme" title="Switch theme">
		<svg class="mt-theme__moon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"
			><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"></path></svg
		>
		<svg class="mt-theme__sun" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"
			><circle cx="12" cy="12" r="4"></circle><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"></path></svg
		>
	</button>
</mt-theme-toggle>

<script>
	const storageKey = 'starlight-theme';
	const system = () => (matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
	const stored = () => {
		try {
			const value = localStorage.getItem(storageKey);
			return value === 'light' || value === 'dark' ? value : null;
		} catch {
			return null;
		}
	};
	const label = (button: HTMLButtonElement) => {
		const next = document.documentElement.dataset.theme === 'light' ? 'dark' : 'light';
		button.setAttribute('aria-label', `Switch to ${next} theme`);
	};

	class ThemeToggle extends HTMLElement {
		connectedCallback() {
			const button = this.querySelector('button')!;
			document.documentElement.dataset.theme = stored() ?? system();
			label(button);
			button.addEventListener('click', () => {
				const next = document.documentElement.dataset.theme === 'light' ? 'dark' : 'light';
				document.documentElement.dataset.theme = next;
				try {
					localStorage.setItem(storageKey, next);
				} catch {}
				for (const b of document.querySelectorAll<HTMLButtonElement>('mt-theme-toggle button')) label(b);
			});
			matchMedia('(prefers-color-scheme: light)').addEventListener('change', () => {
				if (!stored()) {
					document.documentElement.dataset.theme = system();
					label(button);
				}
			});
		}
	}
	customElements.define('mt-theme-toggle', ThemeToggle);
</script>

<style>
	.mt-theme {
		display: inline-grid;
		place-items: center;
		width: 2.1rem;
