// Starlight route middleware: per-page fixes that depend on where a page sits.
import { defineRouteMiddleware } from '@astrojs/starlight/route-data';
import { summarize } from './lib/summary.mjs';

export const onRequest = defineRouteMiddleware((context) => {
	const route = context.locals.starlightRoute;
	const { id, entry } = route;
	const data = entry.data as Record<string, any>;
	const isArchive = id === 'docs/2.x' || id.startsWith('docs/2.x/');
	const isPartial = id.startsWith('docs/sections/');

	// The 2.x archive and the Markdown partials stay out of search.
	if (isArchive || isPartial) data.pagefind = false;

	// A command page's headings are SYNOPSIS, SYNTAX, EXAMPLE 1…23, -Parameter…: list only the sections.
	if (/^docs\/commands\/[^/]+$/.test(id)) route.toc && (route.toc.items = route.toc.items.filter((item) => item.depth <= 2));

	// A page without a description of its own gets its first paragraph, not the site's description.
	if (!data.description && entry.body) {
		const description = summarize(entry.body);
		if (description) {
			data.description = description;
			for (const tag of route.head) {
				const attrs = tag.attrs ?? {};
				if (attrs.name === 'description' || attrs.property === 'og:description' || attrs.name === 'twitter:description') attrs.content = description;
			}
		}
	}
});

// A plain-text summary of Markdown for a meta description: the first real paragraph, without Markdown syntax, cut
// at a sentence or word boundary at most `max` characters long. Used for test pages (scripts/generate-test-docs.mjs)
// and for any docs page without a description of its own (src/routeData.ts).

export function plain(markdown) {
	return String(markdown ?? '')
		.replace(/^---[\s\S]*?^---/m, '')
		.replace(/^(import|export)\s.*$/gm, '')
		.replace(/\{\/\*[\s\S]*?\*\/\}|<!--[\s\S]*?-->/g, '')
		.replace(/^(```|~~~)[\s\S]*?^\1/gm, '')
		.replace(/<[^>]+>/g, ' ')
		.replace(/!\[[^\]]*\]\([^)]*\)/g, '')
		.replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
		.replace(/https?:\/\/\S+/g, '')
		.replace(/`([^`]*)`/g, '$1')
		.replace(/(\*\*|__|\*|_)(\S[^*_]*?)\1/g, '$2')
		.replace(/\\([!-/:-@[-`{-~])/g, '$1');
}

export function summarize(markdown, max = 155) {
	const blocks = plain(markdown)
		.split(/\n\s*\n/)
		.map((b) => b.trim())
		// Skip headings, admonitions, tables, lists of links and labels such as "Learn more:".
		.filter((b) => b && !/^(#{1,6}\s|:::|\||[-*+]\s|\d+\.\s|>\s)/.test(b) && b.replace(/\s+/g, ' ').length >= 40);
	const first = blocks[0]?.replace(/\s+/g, ' ').replace(/\s*(Learn more|See also|Remediation action):?.*$/i, '').trim();
	if (!first) return '';
	if (first.length <= max) return first;
	const cut = first.slice(0, max);
	const sentence = cut.match(/^(.{60,}[.!?])\s/);
	if (sentence) return sentence[1];
	return `${cut.slice(0, cut.lastIndexOf(' ')).replace(/[,;:\s]+$/, '')}…`;
}

