if (autoplay) {
	// 'waiting' until it first comes into view, 'preview' while it plays (or is paused) muted, and done once
	// the viewer has pressed play: from then on, scrolling never starts or stops it.
	let running = false;
	const inView = new IntersectionObserver(
		async (entries) => {
			const visible = entries.some((entry) => entry.isIntersecting);
			const ours = preview || !start.hidden;
			if (visible && ours && !running) {
				running = true;
				await load();
				if (!preview && start.hidden) return; // the viewer pressed play while it loaded
				preview = true;
				player.muted = true;
				start.hidden = true;
				if (sound) sound.hidden = false;
				player.play();
			} else if (!visible && preview && running) {
				running = false;
				player.pause();
			}
		},
		{ threshold: 0.5 },
	);
	inView.observe(this.querySelector('.mt-ex__frame')!);
	start.addEventListener('click', () => inView.disconnect());
	sound?.addEventListener('click', () => inView.disconnect());
}

