	const start = text.indexOf('export const testResults =');
	const objectStart = text.indexOf('{', start);
	const objectEnd = text.search(/\n}\s*;?\s*\n/) + 2;
	return new Function(`return (${text.slice(objectStart, objectEnd)})`)();
}

