		color: #71717a;
		margin-inline-end: 0.4rem;
	}
	button {
		font: inherit;
		font-size: 0.75rem;
		border: 0;
		background: #3f3f46;
		color: #fff;
		border-radius: 6px;
		padding: 0.3rem 0.55rem;
		cursor: pointer;
		flex: none;
	}
	.mt-install__note {
		margin: 0;
		font-size: 0.8rem;
		color: var(--sl-color-gray-3);
	}
	.mt-install--hero .mt-install__note {
		text-align: center;
	}
