<script>
	class TestCatalog extends HTMLElement {
		connectedCallback() {
			const controls = [...this.querySelectorAll<HTMLInputElement | HTMLSelectElement>('[data-filter]')];
			const rows = [...this.querySelectorAll<HTMLTableRowElement>('tbody tr')];
			const cmd = this.querySelector('[data-cmd]')!;
			const countEl = this.querySelector('[data-count]')!;
			const more = this.querySelector<HTMLButtonElement>('[data-more]')!;
			const empty = this.querySelector<HTMLElement>('[data-empty]')!;
			const resets = [...this.querySelectorAll<HTMLButtonElement>('[data-reset]')];
			const pageSize = 100;
			let showAll = false;
			const value = (name: string) => {
				const el = controls.find((c) => c.dataset.filter === name)!;
				return el instanceof HTMLInputElement && el.type === 'checkbox' ? (el.checked ? '1' : '') : el.value;
			};
			const apply = () => {
				const q = value('q').trim().toLowerCase();
				const suite = value('suite');
				const product = value('product');
				const severity = value('severity');
				const preview = value('preview');
				let shown = 0;
				let listed = 0;
				for (const row of rows) {
					const d = row.dataset;
					const match =
						(!q || d.q!.includes(q)) &&
						(!suite || d.suite === suite) &&
						(!product || d.product === product) &&
						(!severity || d.severity === severity) &&
						(!preview || d.preview === '1');
					if (match) shown++;
					// Long lists show the first page; "Show all" lists the rest.
					const visible = match && (showAll || shown <= pageSize);
					row.hidden = !visible;
					if (visible) listed++;
				}
				more.hidden = shown <= listed;
				more.textContent = `Show all ${shown} checks`;
				empty.hidden = shown > 0;
				const filtered = ['q', 'suite', 'product', 'severity', 'preview'].some((name) => value(name));
				resets[0].hidden = !filtered;
				countEl.textContent = `${shown} check${shown === 1 ? '' : 's'}`;
				const parts = ['Invoke-Maester'];
src/components/TestCatalog.astro

				const parts = ['Invoke-Maester'];
				if (suite) parts.push(`-Suite ${suite}`);
				if (product) parts.push(`-Product ${product}`);
				if (severity) parts.push(`-Severity ${severity}`);
				if (q && shown > 0 && shown <= 5) parts.push(`-TestId ${rows.filter((r) => !r.hidden).map((r) => r.querySelector('a')!.textContent).join(',')}`);
				cmd.textContent = parts.join(' ');
				const params = new URLSearchParams();
				for (const name of ['q', 'suite', 'product', 'severity', 'preview']) if (value(name)) params.set(name, value(name));
				history.replaceState(null, '', params.size ? `?${params}` : location.pathname);
			};
			const initial = new URLSearchParams(location.search);
			for (const c of controls) {
				const v = initial.get(c.dataset.filter!);
				if (v) {
					if (c instanceof HTMLInputElement && c.type === 'checkbox') c.checked = v === '1';
					else c.value = v;
				}
				c.addEventListener('input', apply);
			}
			more.addEventListener('click', () => {
				showAll = true;
				apply();
			});
			for (const reset of resets) {
				reset.addEventListener('click', () => {
					for (const c of controls) {
						if (c instanceof HTMLInputElement && c.type === 'checkbox') c.checked = false;
						else c.value = '';
					}
					showAll = false;
					apply();
				});
			}
			this.querySelector('[data-copy]')?.addEventListener('click', (e) => {
				navigator.clipboard.writeText(cmd.textContent ?? '');
				(e.target as HTMLButtonElement).textContent = 'Copied';
				setTimeout(() => ((e.target as HTMLButtonElement).textContent = 'Copy'), 1500);
			});
			apply();
		}
	}
	customElements.define('mt-test-catalog', TestCatalog);
