	}
	.post__share {
		display: flex;
		gap: 1.25rem;
		font-size: 0.88rem;
	}
	.post__share a {
		color: var(--sl-color-gray-2);
	}

	.post__more {
		margin: 5rem 0 0;
		padding-top: 3rem;
		border-top: 1px solid var(--sl-color-gray-5);
	}
	.post__more h2 {
		margin: 0 0 1.5rem;
		font-size: 1.5rem;
		letter-spacing: -0.02em;
		color: var(--sl-color-white);
