  const history = new Map(); // current repo-relative path -> [{ email, name, date }]
  let author = null;
  for (const line of raw.split("\n")) {
    if (line.startsWith("")) {
      const [email, name, date] = line.slice(1).split("");
      author = { email, name, date };
